def num(x, d=0):
    """Format angka gaya Indonesia: titik = pemisah ribuan, koma = desimal (contoh 1.234.567,89)."""
    try:
        if x is None or pd.isna(x):
            return "-"
    except (TypeError, ValueError):
        pass
    s = f"{float(x):,.{d}f}"
    return s.replace(",", "§").replace(".", ",").replace("§", ".")


def rp(n):
    return "Rp " + num(n)


def pct(x, d=1):
    return num(x * 100, d) + "%"


# format kolom tabel (dipakai oleh show)
F = {'int': lambda v: num(v, 0), 'f1': lambda v: num(v, 1), 'f2': lambda v: num(v, 2),
     'f4': lambda v: num(v, 4), 'pct1': lambda v: pct(v, 1), 'pct2': lambda v: pct(v, 2)}


def styled(df, fmt=None):
    """Beri format angka Indonesia pada semua kolom numerik tabel."""
    fmt = fmt or {}
    f = {}
    for c in df.columns:
        if c in fmt:
            f[c] = F[fmt[c]] if isinstance(fmt[c], str) else fmt[c]
        elif pd.api.types.is_bool_dtype(df[c]):
            continue
        elif pd.api.types.is_numeric_dtype(df[c]):
            whole = bool(df[c].dropna().apply(lambda v: float(v).is_integer()).all())
            f[c] = F['int'] if whole else F['f2']
    return df.style.format(f, na_rep="") if f else df.style


def excel_bytes(sheets):
    bio = BytesIO()
    with pd.ExcelWriter(bio, engine='openpyxl') as w:
        for name, d in sheets.items():
            d.to_excel(w, sheet_name=name[:31], index=False)
    return bio.getvalue()


def csv_bytes(df):
    return df.to_csv(index=False).encode('utf-8-sig')


MS_DEF, MC_DEF = 0.01, 0.20  # parameter Apriori bawaan (dipakai dashboard & rekomendasi)



# =====================================================================  ANALISIS DATA
def load_excel(file):
    x = pd.ExcelFile(file)
    get = lambda n: x.parse(n) if n in x.sheet_names else None
    raw = get('Data_Raw')
    if raw is None:
        raise ValueError("Sheet Data_Raw tidak ditemukan")
    prod = get('Data_Produk')
    if prod is None:  # fallback: bentuk katalog dari data mentah
        ok = raw[(raw.Unit_Price > 0) & (raw.Unit_Price < 1e5)]
        prod = ok.groupby('Product_Name').agg(Product_ID=('Product_ID', 'first'), Category=('Category', 'first'),
                                              Reference_Unit_Price_Rp=('Unit_Price', 'median')).reset_index()
    cust = get('Data_Pelanggan')
    if cust is None:
        cust = pd.DataFrame(columns=['Customer_ID', 'Region', 'Customer_Type'])
    return raw, prod, cust, get('Data_Dictionary')


def audit(raw, prod):
    a = {'baris': len(raw), 'kolom': raw.shape[1], 'tgl_min': raw.Transaction_Date.min(), 'tgl_max': raw.Transaction_Date.max(),
         'transaksi': raw.Transaction_ID.nunique(), 'pelanggan': raw.Customer_ID.nunique(), 'produk': raw.Product_Name.nunique(),
         'avg_qty': raw.Quantity.mean(), 'sales': raw.Line_Total.sum(), 'missing': raw.isna().sum()}
    a['dup'] = int(raw.duplicated().sum())
    a['cat_bad'] = int((raw.Category.notna() & ~raw.Category.isin(prod.Category.unique())).sum())
    a['pay_bad'] = int((raw.Payment_Method.notna() & ~raw.Payment_Method.isin(['Tunai', 'Debit', 'Transfer', 'QRIS'])).sum())
    a['qty_bad'] = int(((raw.Quantity <= 0) | (raw.Quantity > 20)).sum())
    a['price_bad'] = int(((raw.Unit_Price <= 0) | (raw.Unit_Price > 1e5)).sum())
    exp = raw.Quantity * raw.Unit_Price * (1 - raw.Discount_Rate)
    a['lt_bad'] = int(((exp - raw.Line_Total).abs() > 1).sum())
    q1, q3 = raw.Quantity.quantile([.25, .75])
    a['iqr'] = q3 + 1.5 * (q3 - q1)
    return a


def clean(raw, prod, cust):
    log = {}
    df = raw.copy()
    n0 = len(df)
    df = df.drop_duplicates()
    log['Baris duplikat dihapus'] = n0 - len(df)
    df['Product_Name'] = df.Product_Name.astype(str).str.strip()
    pm = prod.drop_duplicates('Product_Name').set_index('Product_Name')
    log['Product_ID kosong diisi dari katalog'] = int(df.Product_ID.isna().sum())
    df['Product_ID'] = df.Product_Name.map(pm.Product_ID).fillna(df.Product_ID)
    cat = df.Product_Name.map(pm.Category)
    log['Kategori dinormalkan'] = int((cat.notna() & (cat != df.Category)).sum())
    df['Category'] = cat.fillna(df.Category.astype(str).str.strip().str.title())
    mp = {'tunai': 'Tunai', 'debit': 'Debit', 'transfer': 'Transfer', 'qris': 'QRIS'}
    pay = df.Payment_Method.astype('string').str.strip().str.lower().map(mp)
    log['Payment_Method dinormalkan'] = int((pay.notna() & (pay != df.Payment_Method)).sum())
    log['Payment_Method kosong -> "Tidak Diketahui"'] = int(pay.isna().sum())
    df['Payment_Method'] = pay.fillna('Tidak Diketahui').astype(str)
    cm = cust.drop_duplicates('Customer_ID').set_index('Customer_ID')
    n_fill = 0
    for f in ['Region', 'Customer_Type']:
        m = df[f].isna()
        if f in cm:
            df.loc[m, f] = df.loc[m, 'Customer_ID'].map(cm[f])
        n_fill += int(m.sum() - df[f].isna().sum())
        df[f] = df[f].fillna('Tidak Diketahui')
    log['Region/Customer_Type diisi dari Data_Pelanggan'] = n_fill
    log['Customer_ID kosong (dipertahankan, dikeluarkan dari RFM)'] = int(df.Customer_ID.isna().sum())
    ref = df.Product_ID.map(prod.drop_duplicates('Product_ID').set_index('Product_ID').Reference_Unit_Price_Rp)
    bad = df.Unit_Price.isna() | (df.Unit_Price <= 0) | (df.Unit_Price > 1e5)
    df.loc[bad, 'Unit_Price'] = ref[bad]
    log['Unit_Price diganti harga referensi'] = int(bad.sum())
    df = df[df.Unit_Price.notna()]
    bad = df.Quantity.isna() | (df.Quantity <= 0) | (df.Quantity > 20)
    est = (df.Line_Total / (df.Unit_Price * (1 - df.Discount_Rate))).round()
    ok = bad & est.between(1, 20)
    df.loc[ok, 'Quantity'] = est[ok]
    log['Quantity diperbaiki dari Line_Total'] = int(ok.sum())
    log['Quantity tak terpulihkan (dihapus)'] = int((bad & ~ok).sum())
    df = df[~(bad & ~ok)]
    exp = (df.Quantity * df.Unit_Price * (1 - df.Discount_Rate)).round()
    fix = df.Line_Total.isna() | ((df.Line_Total - exp).abs() > 1)
    df.loc[fix, 'Line_Total'] = exp[fix]
    log['Line_Total dihitung ulang'] = int(fix.sum())
    df['Quantity'] = df.Quantity.astype(int)
    df['Transaction_Date'] = pd.to_datetime(df.Transaction_Date)
    df['Month'] = df.Transaction_Date.dt.strftime('%Y-%m')
    return df.reset_index(drop=True), log


def build_features(df):
    tx = df.groupby('Transaction_ID').agg(date=('Transaction_Date', 'first'), cust=('Customer_ID', 'first'),
                                          basket_size=('Product_ID', 'nunique'), total=('Line_Total', 'sum')).reset_index()
    baskets = df.groupby('Transaction_ID').Product_Name.apply(lambda s: tuple(sorted(set(s)))).tolist()
    ref = df.Transaction_Date.max().normalize() + pd.Timedelta(days=1)
    t = tx.dropna(subset=['cust'])
    rfm = t.groupby('cust').agg(last=('date', 'max'), Frequency=('Transaction_ID', 'nunique'), Monetary=('total', 'sum')).reset_index()
    rfm['Recency'] = (ref - rfm['last'].dt.normalize()).dt.days
    rfm = rfm.rename(columns={'cust': 'Customer_ID'})[['Customer_ID', 'Recency', 'Frequency', 'Monetary']]
    return tx, baskets, rfm, ref


def apriori(baskets, ms, mc):
    n = len(baskets)
    mn = ms * n
    c1 = Counter(i for b in baskets for i in b)
    f1 = {i for i, c in c1.items() if c >= mn}
    sup = {(i,): c for i, c in c1.items() if i in f1}
    c2 = Counter()
    for b in baskets:
        c2.update(combinations([i for i in b if i in f1], 2))
    f2 = {k: v for k, v in c2.items() if v >= mn}
    sup.update(f2)
    c3 = Counter()
    for b in baskets:
        for t in combinations([i for i in b if i in f1], 3):
            if all(p in f2 for p in combinations(t, 2)):
                c3[t] += 1
    f3 = {k: v for k, v in c3.items() if v >= mn}
    sup.update(f3)
    rules = []
    for s in list(f2) + list(f3):
        for r in range(1, len(s)):
            for A in combinations(s, r):
                C = tuple(x for x in s if x not in A)
                conf = sup[s] / sup[A]
                if conf >= mc:
                    rules.append({'Antecedent': ' + '.join(A), 'Consequent': ' + '.join(C), 'A': A, 'C': C, 'Support': sup[s] / n,
                                  'Confidence': conf, 'Lift': conf / (sup[C] / n), 'Transaksi': sup[s]})
    rd = pd.DataFrame(rules, columns=['Antecedent', 'Consequent', 'A', 'C', 'Support', 'Confidence', 'Lift', 'Transaksi'])
    n_all = len(rd)
    rd = rd[rd.Lift > 1].sort_values(['Lift', 'Confidence'], ascending=False).reset_index(drop=True)
    sets = pd.DataFrame([{'Itemset': ' + '.join(k), 'Transaksi': v, 'Support': v / n} for k, v in {**f2, **f3}.items()])
    if len(sets):
        sets = sets.sort_values('Transaksi', ascending=False).reset_index(drop=True)
    return {'n': n, 'f1': len(f1), 'f2': len(f2), 'f3': len(f3), 'n_rules': n_all, 'rules': rd, 'sets': sets}


def kmeans_eval(rfm):
    X = StandardScaler().fit_transform(rfm[['Recency', 'Frequency', 'Monetary']])
    rows = []
    for k in range(2, 9):
        km = KMeans(n_clusters=k, n_init=10, random_state=42).fit(X)
        rows.append({'k': k, 'Inertia': km.inertia_, 'Silhouette': silhouette_score(X, km.labels_), 'labels': km.labels_})
    return X, rows


def label_segments(rfm, labels):
    d = rfm.copy()
    d['Cluster'] = labels
    g = d[['Recency', 'Frequency', 'Monetary']].mean()
    used, names = {}, {}
    for c, a in d.groupby('Cluster'):
        r, f, m = a.Recency.mean(), a.Frequency.mean(), a.Monetary.mean()
        if r < g.Recency and f > g.Frequency and m > g.Monetary:
            lb = 'Loyal Customers'
        elif r > g.Recency and f < g.Frequency:
            lb = 'Churn Risk'
        elif r < g.Recency and f < g.Frequency:
            lb = 'New Customers'
        elif f >= g.Frequency or m >= g.Monetary:
            lb = 'Potential Customers'
        else:
            lb = 'Regular Customers'
        used[lb] = used.get(lb, 0) + 1
        names[c] = lb if used[lb] == 1 else f"{lb} ({used[lb]})"
    d['Segmen'] = d.Cluster.map(names)
    prof = d.groupby('Segmen').agg(Pelanggan=('Customer_ID', 'count'), Recency_rata=('Recency', 'mean'), Recency_median=('Recency', 'median'),
                                   Frequency_rata=('Frequency', 'mean'), Frequency_median=('Frequency', 'median'),
                                   Monetary_rata=('Monetary', 'mean'), Monetary_median=('Monetary', 'median'),
                                   Total=('Monetary', 'sum')).reset_index()
    prof['Kontribusi'] = prof.Total / prof.Total.sum()
    prof['Strategi'] = prof.Segmen.map(lambda s: STRAT.get(s.split()[0], STRAT['Regular']))
    return d, prof


def process(file):
    raw, prod, cust, dic = load_excel(file)
    for c in raw.select_dtypes('object'):
        pass
    raw['Transaction_Date'] = pd.to_datetime(raw.Transaction_Date)
    clean_df, log = clean(raw, prod, cust)
    tx, baskets, rfm, ref = build_features(clean_df)
    X, kr = kmeans_eval(rfm)
    best = max([r for r in kr if 3 <= r['k'] <= 6], key=lambda r: r['Silhouette'])['k']
    return dict(raw=raw, prod=prod, cust=cust, dic=dic, aud=audit(raw, prod), df=clean_df, log=log, tx=tx, baskets=baskets,
                rfm=rfm, ref=ref, X=X, kr=kr, k=best)



