def urow(text, done):
    return f'<div class="urow {"" if done else "wait"}"><span class="pct">{"100%" if done else "..."}</span><span class="nm">{text}</span><span class="ok">{"✓" if done else ""}</span></div>'


def unique_rules(r, n):
    """Ambil n aturan teratas tanpa kebalikan pasangan yang sama (A->B dan B->A dihitung satu)."""
    seen, out = set(), []
    for _, x in r.iterrows():
        key = frozenset(x.A) | frozenset(x.C)
        if key in seen:
            continue
        seen.add(key)
        out.append(x)
        if len(out) == n:
            break
    return out


def basket_matrix(df):
    return pd.crosstab(df.Transaction_ID, df.Product_Name).gt(0).astype(int)


