@st.cache_data(show_spinner=False)
def apriori_cached(baskets, ms, mc):
    return apriori(list(baskets), ms, mc)


def lift_heatmap(r, baskets, max_products=10):
    """Heatmap Lift simetris dan padat, dihitung dari seluruh basket, bukan hanya aturan teratas.

    Setiap sel menunjukkan lift pasangan produk A-B. Nilai dihitung dari support(A dan B)
    dibagi support(A)*support(B), sehingga pasangan tetap terlihat meskipun aturan tidak lolos
    ambang confidence. Produk dipilih berdasarkan frekuensi transaksi agar matriks terbaca.
    """
    baskets = [set(b) for b in baskets]
    freq = Counter(item for basket in baskets for item in basket)
    products = [name for name, _ in freq.most_common(max_products)]
    n = len(baskets)
    if n < 1 or len(products) < 2:
        return None

    matrix = pd.DataFrame(np.nan, index=products, columns=products, dtype=float)
    support = {p: freq[p] / n for p in products}
    for i, a in enumerate(products):
        for j, b in enumerate(products):
            if a == b:
                continue
            together = sum(1 for basket in baskets if a in basket and b in basket)
            pair_support = together / n
            denom = support[a] * support[b]
            # Nol jika tidak pernah muncul bersama; selain itu lift statistik standar.
            matrix.loc[a, b] = (pair_support / denom) if denom > 0 else 0.0

    vals = matrix.to_numpy(dtype=float)
    valid = vals[np.isfinite(vals)]
    if valid.size == 0:
        return None
    vmax = max(float(np.nanpercentile(valid, 95)), 1.0)
    fig = px.imshow(
        matrix,
        text_auto='.2f',
        aspect='equal',
        color_continuous_scale='YlGnBu',
        labels=dict(x='Produk', y='Produk', color='Lift'),
        title='Heatmap Lift Antarproduk',
        zmin=0,
        zmax=vmax,
    )
    fig.update_xaxes(side='bottom', tickangle=-90, automargin=True, tickfont=dict(size=10))
    fig.update_yaxes(automargin=True, tickfont=dict(size=10), autorange='reversed')
    fig.update_traces(hovertemplate='Produk A: %{y}<br>Produk B: %{x}<br>Lift: %{z:.2f}<extra></extra>')
    fig.update_layout(
        height=max(600, 48 * len(products) + 190),
        width=None,
        autosize=True,
        margin=dict(l=145, r=85, t=100, b=155),
        coloraxis_colorbar=dict(title='Lift', thickness=16, len=0.78),
    )
    return fig


def page_apr(D):
    st.header("Apriori / Market Basket Analysis")
    st.subheader("Tugas 9–10 — Matriks Transaksi dan Frequent Itemsets")
    tx, df = D['tx'], D['df']
    st.markdown(f"**Matriks transaksi** (contoh 6 transaksi x 8 produk; matriks lengkap {num(len(D['baskets']))} x {num(df.Product_Name.nunique())} dapat diunduh pada menu Data Preprocessing)")
    items = sorted({i for b in D['baskets'] for i in b})[:8]
    mat = pd.DataFrame([[int(i in b) for i in items] for b in D['baskets'][:6]], columns=items)
    mat.insert(0, 'Transaksi', [f"basket {i + 1}" for i in range(6)])
    show(mat, hide_index=True)
    st.markdown("**Minimum support dan minimum confidence**")
    ms = st.slider("Minimum support (%)", 0.5, 5.0, MS_DEF * 100, 0.5) / 100
    mc = st.slider("Minimum confidence (%)", 10, 60, int(MC_DEF * 100), 5) / 100
    A = apriori_cached(tuple(D['baskets']), ms, mc)
    st.markdown(f"""**Alasan nilai:** rata-rata basket hanya {num(tx.basket_size.mean(), 2)} produk unik dari {num(df.Product_Name.nunique())} produk, sehingga pasangan produk jarang memiliki support tinggi. Support {pct(ms)} setara sekitar {num(ms * A['n'])} dari {num(A['n'])} transaksi: cukup besar agar pola stabil (bukan kebetulan) tetapi tidak membuang pola yang berguna. Confidence {pct(mc, 0)} berarti aturan berlaku pada minimal 1 dari {num(1 / mc, 0)} keranjang yang memuat antecedent. Nilai awal yang disarankan: support 1% dan confidence 20%.""")
    st.markdown("**Frequent itemsets**")
    kpis([("Transaksi (basket)", num(A['n'])), ("Frequent 1-itemset", num(A['f1'])), ("Frequent 2-itemset", num(A['f2'])), ("Frequent 3-itemset", num(A['f3'])), ("Aturan (conf >= min)", num(A['n_rules']))])
    if len(A['sets']):
        show(A['sets'].head(10), fmt={'Support': 'pct2'}, hide_index=True)
    r = A['rules']
    if r.empty:
        st.warning("Tidak ada aturan pada ambang ini; turunkan support/confidence.")
        return
    st.markdown("**d, e, f. Aturan asosiasi (support, confidence, lift) - maksimal 10 aturan terbaik**")
    st.caption("Kriteria peringkat: hanya aturan dengan lift > 1 (hubungan positif), diurutkan dari lift terbesar, lalu confidence terbesar. Lift > 1 berarti produk dibeli bersama lebih sering daripada kebetulan.")
    top = r.head(10).copy()
    tshow = top[['Antecedent', 'Consequent', 'Support', 'Confidence', 'Lift', 'Transaksi']].copy()
    tshow.index = range(1, len(tshow) + 1)
    show(tshow, fmt={'Support': 'pct2', 'Confidence': 'pct1', 'Lift': 'f2'})
    st.markdown("**Heatmap Lift antarproduk**")
    st.caption("Matriks simetris membandingkan semua pasangan dari 10 produk yang paling sering muncul. Setiap sel dihitung langsung dari seluruh transaksi, bukan hanya dari aturan yang lolos ambang confidence. Lift > 1 menunjukkan pasangan muncul bersama lebih sering daripada perkiraan independen; lift < 1 menunjukkan lebih jarang.")
    hm = lift_heatmap(r, D['baskets'])
    if hm is not None:
        pc(hm)
    else:
        st.info("Belum ada aturan asosiasi pasangan produk yang cukup untuk membentuk heatmap. Coba turunkan minimum support atau confidence.")

    # Grafik batang 10 aturan dengan Lift tertinggi, diminta untuk melengkapi heatmap.
    st.markdown("**10 Aturan Asosiasi dengan Lift Tertinggi**")
    bar_rules = r.sort_values(['Lift', 'Confidence'], ascending=[False, False]).head(10).copy()
    if not bar_rules.empty:
        bar_rules['Aturan'] = bar_rules['Antecedent'].astype(str) + ' → ' + bar_rules['Consequent'].astype(str)
        fig_lift = px.bar(
            bar_rules.sort_values('Lift', ascending=True),
            x='Lift', y='Aturan', orientation='h',
            text=bar_rules.sort_values('Lift', ascending=True)['Lift'].map(lambda v: f'{v:.2f}'),
            color='Lift', color_continuous_scale='YlGnBu',
            labels={'Lift': 'Nilai Lift', 'Aturan': 'Aturan asosiasi'},
            title='10 Aturan Asosiasi Berdasarkan Lift Tertinggi'
        )
        fig_lift.update_traces(textposition='outside', cliponaxis=False)
        fig_lift.update_layout(height=max(430, 42 * len(bar_rules) + 170), coloraxis_showscale=False,
                               margin=dict(l=210, r=75, t=105, b=65))
        pc(fig_lift)
    st.download_button("Unduh aturan asosiasi (CSV)", csv_bytes(r[['Antecedent', 'Consequent', 'Support', 'Confidence', 'Lift', 'Transaksi']]), file_name="aturan_apriori.csv", mime="text/csv")

    st.subheader("Tugas 11–12 — Aturan Asosiasi, Visualisasi, dan Rekomendasi")
    U = unique_rules(r, 5)
    t = U[0]
    st.markdown(f"""**Kombinasi paling menarik untuk bisnis:** **{t.Antecedent} → {t.Consequent}**, karena memiliki lift tertinggi ({num(t.Lift, 2)}) dengan confidence {pct(t.Confidence)}. Kombinasi lain: """ + "; ".join(f"{x.Antecedent} → {x.Consequent} (lift {num(x.Lift, 2)})" for x in U[1:4]) + ".")
    st.markdown(f"""**Arti nilai pada aturan terpilih:**
- **Support {pct(t.Support, 2)}**: kedua produk muncul bersama pada {pct(t.Support, 2)} dari seluruh transaksi ({num(t.Transaksi)} nota).
- **Confidence {pct(t.Confidence)}**: dari semua keranjang yang berisi {t.Antecedent}, {pct(t.Confidence)} juga berisi {t.Consequent}.
- **Lift {num(t.Lift, 2)}**: peluang kedua produk dibeli bersama {num(t.Lift, 2)} kali lebih besar daripada jika dibeli secara independen. Aturan asosiasi menunjukkan keterkaitan, bukan sebab-akibat.""")
    st.markdown("**Rekomendasi cross-selling / bundling**")
    for x, tag in zip(U[:3], ['Bundling paket', 'Cross-selling di kasir/aplikasi', 'Promo pembelian bersama']):
        st.markdown(f"- **{tag}:** {x.Antecedent} + {x.Consequent}. *Alasan:* support {pct(x.Support, 2)}, confidence {pct(x.Confidence)}, lift {num(x.Lift, 2)} dari {num(x.Transaksi)} transaksi nyata, sehingga penawaran dibuat pada pasangan yang terbukti sering dibeli bersama.")
    st.markdown("**Produk yang layak ditempatkan berdekatan di rak/etalase**")
    for x in U:
        st.markdown(f"- {x.Antecedent} berdekatan dengan {x.Consequent} (lift {num(x.Lift, 2)}).")
    st.markdown("**Dasar alasan:** seluruh rekomendasi bersumber dari nilai support, confidence, dan lift di atas (bukan perkiraan). Dampak penjualan sebenarnya baru dapat diketahui setelah uji coba (pilot).")


