def page_dash(D):
    st.header("Dashboard Business Intelligence")
    st.subheader("Tugas 17–19 — KPI, Analisis, dan Insight Dashboard")
    df = D['df'].copy()
    d, prof = current_segments(D)
    df['Segmen'] = df.Customer_ID.map(d.set_index('Customer_ID').Segmen)
    months = sorted(df.Month.unique())
    st.markdown("**Filter interaktif**")
    c1, c2, c3 = st.columns(3)
    m1, m2 = c1.select_slider("Periode transaksi", months, value=(months[0], months[-1]))
    cat = c2.selectbox("Kategori produk", ['Semua'] + sorted(df.Category.unique()))
    seg = c3.selectbox("Segmen pelanggan", ['Semua'] + sorted(prof.Segmen))
    f = df[(df.Month >= m1) & (df.Month <= m2)]
    if cat != 'Semua':
        f = f[f.Category == cat]
    if seg != 'Semua':
        f = f[f.Segmen == seg]
    if f.empty:
        st.warning("Tidak ada data pada kombinasi filter ini.")
        return
    bs = f.groupby('Transaction_ID').Product_ID.nunique()
    st.markdown("**Key Performance Indicators**")
    kpis([("Total penjualan", rp(f.Line_Total.sum())), ("Jumlah transaksi", num(f.Transaction_ID.nunique())),
          ("Pelanggan unik", num(f.Customer_ID.nunique())), ("Rata-rata basket_size", num(bs.mean(), 2))])
    st.info(f"**Informasi untuk manajemen:** pada filter ini terjadi {num(f.Transaction_ID.nunique())} transaksi dengan penjualan bersih {rp(f.Line_Total.sum())}, rata-rata {rp(f.Line_Total.sum() / f.Transaction_ID.nunique())} per transaksi dan {num(bs.mean(), 2)} produk berbeda per keranjang. Pelanggan unik = Customer_ID terisi yang bertransaksi pada filter.")
    st.markdown("**Analisis penjualan**")
    mo = f.groupby('Month').Line_Total.sum().reset_index()
    fig_month = px.line(mo, x='Month', y='Line_Total', markers=True, title='Tren penjualan bulanan', labels={'Month': 'Bulan', 'Line_Total': 'Penjualan (Rp)'})
    fig_month.update_layout(height=440, margin=dict(l=25, r=25, t=65, b=55))
    pc(fig_month, y=True)
    tp = f.groupby('Product_Name').Line_Total.sum().nlargest(10).reset_index()
    fig_tp = px.bar(tp, x='Line_Total', y='Product_Name', orientation='h', title='10 produk dengan penjualan tertinggi', labels={'Line_Total': 'Penjualan (Rp)', 'Product_Name': ''}).update_yaxes(autorange='reversed')
    fig_tp.update_layout(height=max(440, 36 * len(tp) + 150), margin=dict(l=25, r=25, t=65, b=55))
    pc(fig_tp, x=True)
    cs = f.groupby('Category').Line_Total.sum().reset_index()
    pie = px.pie(
        cs, names='Category', values='Line_Total', hole=.4,
        title='Distribusi penjualan per kategori'
    )
    pie.update_traces(
        hovertemplate='%{label}<br>Rp %{value:,.0f}<br>%{percent:.1%}<extra></extra>',
        textposition='inside',
        textinfo='percent',
        insidetextorientation='radial'
    )
    # Area pie dibatasi di kiri; legenda memiliki kolom khusus di kanan.
    # Ini mencegah legenda bertumpuk dengan judul maupun label persentase.
    pie.update_traces(domain=dict(x=[0.02, 0.68], y=[0.02, 0.90]))
    pie.update_layout(
        height=640,
        margin=dict(l=30, r=260, t=100, b=45),
        title=dict(text='Distribusi penjualan per kategori', x=0.02, xanchor='left', y=0.99, yanchor='top'),
        legend=dict(
            orientation='v',
            x=0.74, xanchor='left',
            y=0.88, yanchor='top',
            font=dict(size=12),
            title_text='Kategori',
            itemsizing='constant'
        ),
        uniformtext_minsize=10,
        uniformtext_mode='hide'
    )
    pc(pie)
    fig_seg = px.bar(prof, x='Segmen', y='Pelanggan', color='Segmen', title='Jumlah pelanggan per klaster (K-Means)')
    fig_seg.update_layout(height=440, margin=dict(l=25, r=25, t=65, b=55))
    pc(fig_seg, y=True)
    pk = mo.loc[mo.Line_Total.idxmax()]
    lw = mo.loc[mo.Line_Total.idxmin()]
    top_p = tp.iloc[0]
    top_c = cs.loc[cs.Line_Total.idxmax()]
    st.info(f"**Informasi untuk manajemen:** penjualan tertinggi pada {pk.Month} ({rp(pk.Line_Total)}) dan terendah pada {lw.Month} ({rp(lw.Line_Total)}). Produk terlaris {top_p.Product_Name} ({pct(top_p.Line_Total / f.Line_Total.sum())} penjualan) dan kategori terbesar {top_c.Category} ({pct(top_c.Line_Total / f.Line_Total.sum())}).")
    st.markdown("**Analisis Apriori (mengikuti filter; support 1%, confidence 20%)**")
    bk = f.groupby('Transaction_ID').Product_Name.apply(lambda s: tuple(sorted(set(s)))).tolist()
    A = apriori_cached(tuple(bk), MS_DEF, MC_DEF)
    src = "data terfilter"
    if A['rules'].empty:
        A = apriori_cached(tuple(D['baskets']), MS_DEF, MC_DEF)
        src = "seluruh data (filter terlalu sempit untuk membentuk aturan)"
    st.caption(f"Sumber aturan: {src}.")
    r = A['rules'].head(8)
    if len(r):
        show(r[['Antecedent', 'Consequent', 'Support', 'Confidence', 'Lift']], fmt={'Support': 'pct2', 'Confidence': 'pct1', 'Lift': 'f2'}, hide_index=True)
        rb = r.assign(Aturan=r.Antecedent + ' → ' + r.Consequent)
        pc(px.bar(rb, x='Lift', y='Aturan', orientation='h', color='Confidence', title='Kombinasi produk berdasarkan lift').update_yaxes(autorange='reversed'))
        t = r.iloc[0]
        st.info(f"**Informasi untuk manajemen:** kombinasi terkuat {t.Antecedent} → {t.Consequent} (support {pct(t.Support, 2)}, confidence {pct(t.Confidence)}, lift {num(t.Lift, 2)}); jadikan kandidat bundling dan penempatan rak berdekatan.")
    else:
        st.info("Tidak ada aturan asosiasi yang memenuhi ambang pada data ini.")
    st.markdown("**Analisis K-Means (segmen pada pelanggan yang tampil di filter)**")
    dd = d[d.Customer_ID.isin(f.Customer_ID.dropna())]
    st.markdown("**Ringkasan karakteristik segmen pelanggan**")
    show(prof[['Segmen', 'Pelanggan', 'Recency_rata', 'Frequency_rata', 'Monetary_rata', 'Kontribusi']],
         fmt={'Recency_rata': 'f1', 'Frequency_rata': 'f2', 'Monetary_rata': 'int', 'Kontribusi': 'pct1'}, hide_index=True)
    st.markdown("**Visualisasi segmentasi pelanggan**")
    pc(px.scatter(dd, x='Frequency', y='Monetary', color='Segmen', hover_data=['Customer_ID', 'Recency'], title='Visualisasi segmentasi pelanggan'), y=True)
    big = prof.sort_values('Total', ascending=False).iloc[0]
    st.info(f"**Informasi untuk manajemen:** segmen {big.Segmen} menyumbang {pct(big.Kontribusi)} pendapatan dari {num(big.Pelanggan)} pelanggan sehingga perlu dijaga lebih dulu. RFM dihitung dari seluruh periode data; filter periode hanya memengaruhi daftar pelanggan yang tampil.")
    st.subheader("Bonus: produk andalan tiap segmen (sesuai filter)")
    rows = []
    for s, g in f.dropna(subset=['Segmen']).groupby('Segmen'):
        t = g.groupby('Product_Name').Line_Total.sum().nlargest(3)
        rows.append({'Segmen': s, 'Top 3 produk (porsi pendapatan segmen)': ', '.join(f"{n} ({pct(v / g.Line_Total.sum())})" for n, v in t.items())})
    show(pd.DataFrame(rows), hide_index=True)


# =====================================================================  TAHAP 6
def page_rek(D):
    st.header("Rekomendasi Keputusan Bisnis")
    st.subheader("Tugas 20–22 — Rekomendasi Preskriptif dan Evaluasi")
    st.markdown("**Fakta data** = dihitung langsung dari dataset | **Estimasi** = berbasis asumsi | **Dampak aktual** = baru diketahui setelah implementasi.")
    df = D['df']
    d, prof = current_segments(D)
    A = apriori_cached(tuple(D['baskets']), MS_DEF, MC_DEF)
    U = unique_rules(A['rules'], 3) if len(A['rules']) else []
    st.markdown("**Strategi penempatan produk & bundling (Fakta dari Apriori)**")
    if U:
        strategi_rows = []
        for r in U:
            strategi_rows.append({
                'Produk yang dibeli bersama (Antecedent)': r.Antecedent,
                'Produk yang direkomendasikan (Consequent)': r.Consequent,
                'Support': pct(r.Support, 2),
                'Confidence': pct(r.Confidence),
                'Lift': num(r.Lift, 2),
                'Strategi penempatan/bundling': f"Letakkan {r.Antecedent} berdekatan dengan {r.Consequent} dan uji sebagai paket promo."
            })
        # Satu tabel penuh per baris; tidak disejajarkan dengan komponen lain.
        show(pd.DataFrame(strategi_rows), hide_index=True)
        st.caption("Support menunjukkan seberapa sering kombinasi muncul; confidence menunjukkan peluang consequent saat antecedent dibeli; lift di atas 1 menunjukkan asosiasi positif.")
    else:
        st.warning("Tidak ada aturan Apriori pada parameter bawaan (support 1%, confidence 20%).")
    st.markdown("**Strategi retensi pelanggan (Fakta dari K-Means)**")
    for s in prof.sort_values('Total', ascending=False).itertuples():
        if s.Segmen.startswith(('Loyal', 'Churn')):
            st.markdown(f"- **{s.Segmen}** ({num(s.Pelanggan)} pelanggan, {pct(s.Kontribusi)} pendapatan, Recency rata-rata {num(s.Recency_rata, 0)} hari): {s.Strategi}")
    st.markdown(f"- Perbaiki pencatatan Customer_ID: {num(D['aud']['missing']['Customer_ID'])} baris tanpa ID tidak dapat dilacak untuk RFM.")
    st.markdown("**Prioritas tindakan** (penilaian analis, bukan hasil perhitungan data)")
    lv = {'Tinggi': 3, 'Sedang': 2, 'Rendah': 1}
    rec = pd.DataFrame([
        ('Bundling & penempatan rak (Apriori)', 'Tinggi', 'Tinggi', 'Rendah', 'Tinggi', 'Attach rate dan rata-rata basket_size'),
        ('Program loyalitas segmen bernilai tinggi', 'Tinggi', 'Tinggi', 'Sedang', 'Sedang', 'Repeat rate dan Monetary segmen loyal'),
        ('Kampanye win-back segmen berisiko churn', 'Sedang', 'Sedang', 'Sedang', 'Sedang', 'Tingkat reaktivasi pelanggan'),
        ('Perbaikan kualitas data kasir', 'Sedang', 'Sedang', 'Rendah', 'Tinggi', '% transaksi dengan Customer_ID terisi')],
        columns=['Rekomendasi', 'Urgensi', 'Manfaat', 'Biaya', 'Kemudahan', 'KPI utama'])
    rec['Skor'] = rec.Urgensi.map(lv) + rec.Manfaat.map(lv) + (4 - rec.Biaya.map(lv)) + rec.Kemudahan.map(lv)
    rec = rec.sort_values(['Skor', 'Manfaat'], ascending=[False, False], key=lambda s: s.map(lv) if s.name == 'Manfaat' else s).reset_index(drop=True)
    rec.insert(0, 'Peringkat', range(1, len(rec) + 1))
    show(rec, hide_index=True)
    st.caption("Skor = Urgensi + Manfaat + (4 - Biaya) + Kemudahan, tiap komponen skala 1-3 (Rendah-Tinggi); skor lebih tinggi berarti prioritas lebih tinggi.")
    st.markdown("**Estimasi dampak bisnis (Estimasi berbasis asumsi, bukan fakta)**")
    rows, total = [], 0.0
    sets = df.groupby('Transaction_ID').Product_Name.apply(set)
    for r in U:
        has_a = sets[sets.apply(lambda s: set(r.A) <= s)]
        miss = has_a[has_a.apply(lambda s: not set(r.C) <= s)]
        avg = df[df.Product_Name.isin(r.C)].Line_Total.mean()
        v = 0.05 * len(miss) * avg * len(r.C)
        total += v
        rows.append({'Skenario': f"Bundling {r.Antecedent} -> {r.Consequent}", 'Asumsi': f"5% dari {num(len(miss))} transaksi berisi antecedent tanpa consequent menambah consequent",
                     'Indikator keberhasilan': 'Attach rate consequent naik dari baseline', 'Cara mengukur': 'Pilot 1-2 toko vs toko kontrol, bandingkan attach rate dan basket_size',
                     'Estimasi tambahan penjualan/tahun': rp(v)})
    ch = prof[prof.Segmen.str.startswith('Churn')]
    if len(ch):
        c = ch.sort_values('Total', ascending=False).iloc[0]
        v = 0.10 * c.Pelanggan * c.Monetary_rata
        total += v
        rows.append({'Skenario': f"Win-back {c.Segmen}", 'Asumsi': f"10% dari {num(c.Pelanggan)} pelanggan kembali dengan belanja setara rata-rata Monetary ({rp(c.Monetary_rata)})",
                     'Indikator keberhasilan': 'Persentase pelanggan segmen ini yang bertransaksi kembali', 'Cara mengukur': 'Lacak Customer_ID penerima voucher vs kelompok kontrol selama 90 hari',
                     'Estimasi tambahan penjualan/tahun': rp(v)})
    if rows:
        show(pd.DataFrame(rows), hide_index=True)
    st.info(f"Total estimasi sekitar {rp(total)} ({pct(total / df.Line_Total.sum())} dari penjualan bersih {rp(df.Line_Total.sum())}). Ini bukan fakta; uji lewat pilot/A-B test. Dampak aktual baru dapat diukur setelah implementasi.")
    st.markdown("**Rencana implementasi**")
    st.markdown("- **Jangka pendek (0-1 bulan):** pilot bundling 3 aturan teratas di 1-2 toko, susun rak berdekatan, kirim voucher win-back ke segmen berisiko.\n- **Jangka menengah (2-6 bulan):** program poin untuk segmen loyal, jalankan ulang RFM tiap bulan, evaluasi dan perluas bundling.")
    st.markdown("**KPI evaluasi setelah implementasi**")
    st.markdown("- Attach rate consequent saat antecedent dibeli (bandingkan dengan confidence awal) dan rata-rata basket_size.\n- Pendapatan per transaksi dan total penjualan kelompok pilot vs kontrol.\n- Tingkat reaktivasi segmen berisiko churn dan repeat rate segmen loyal.\n- Persentase transaksi dengan Customer_ID terisi.")


def main():
    st.markdown(CSS, unsafe_allow_html=True)
    if not st.session_state.get('entered'):
        # Cover tanpa sidebar.
        st.markdown("<style>[data-testid='stSidebar']{display:none!important}</style>", unsafe_allow_html=True)
        cover()
        return

    has = 'D' in st.session_state
    if not has:
        # Sebelum data berhasil diproses, hanya tampilkan halaman upload.
        st.markdown("<style>[data-testid='stSidebar']{display:none!important}</style>", unsafe_allow_html=True)
        page_upload()
        return

    # Sidebar baru ditampilkan setelah dataset berhasil diproses.
    st.markdown("<style>[data-testid='stSidebar']{display:block!important}</style>", unsafe_allow_html=True)
    header()  # identitas di bagian atas sidebar
    # Menu navigasi berupa tombol, tanpa bulatan radio. Upload hanya tersedia lewat tombol bawah.
    st.sidebar.markdown("<div style='font-size:15px;font-weight:750;color:#24364b;margin:18px 0 10px 4px'>Menu</div>", unsafe_allow_html=True)
    routes = {
        MENU[0]: page_eda,
        MENU[1]: page_pre,
        MENU[2]: page_apr,
        MENU[3]: page_km,
        MENU[4]: page_dash,
        MENU[5]: page_rek,
    }
    if st.session_state.get('menu') not in MENU:
        st.session_state.menu = MENU[0]
    nav_items = [
        ("🧭", MENU[0]),
        ("🧹", MENU[1]),
        ("🛒", MENU[2]),
        ("👥", MENU[3]),
        ("📊", MENU[4]),
        ("💡", MENU[5]),
    ]
    for idx, (icon, item) in enumerate(nav_items):
        active = st.session_state.menu == item
        if st.sidebar.button(item, icon=icon, key=f"nav_{idx}", type="primary" if active else "secondary", use_container_width=True):
            st.session_state.menu = item
            st.rerun()
    st.sidebar.markdown("<div style='height:4px;border-bottom:1px solid #e5e7eb;margin-bottom:6px'></div>", unsafe_allow_html=True)
    if st.sidebar.button("Kembali ke Upload Data", icon="🔄", key="back_to_upload", use_container_width=True):
        reset_upload()
        st.rerun()
    routes[st.session_state.menu](st.session_state.D)


if __name__ == "__main__":
    from streamlit.runtime import exists
    if exists():
        main()
    else:  # dijalankan dengan "python file.py" / tombol Run -> otomatis jalankan lewat streamlit
        import subprocess
        import sys
        subprocess.run([sys.executable, "-m", "streamlit", "run", __file__])
